import { z } from 'zod';

export const MODEL_TYPES = ['prop', 'enemy', 'npc', 'character'] as const;
export type ModelType = (typeof MODEL_TYPES)[number];

export const COLLIDER_KINDS = ['none', 'box', 'trunk', 'mesh'] as const;
export type ColliderKind = (typeof COLLIDER_KINDS)[number];

/** One model in public/assets/manifest.json (generated by scripts/build-manifest.mjs). */
export const ManifestModel = z.object({
  id: z.string().min(1),
  /** Relative to the site root, e.g. "assets/kenney/…/tree_oak.glb". */
  path: z.string().min(1),
  type: z.enum(MODEL_TYPES),
  licence: z.string().min(1),
  pack: z.string(),
  format: z.enum(['glb', 'fbx']),
  /** Multiply the file's units by this to get metres. */
  baseScale: z.number().positive(),
  collider: z.enum(COLLIDER_KINDS),
  /** Bounding size in metres after baseScale [x, y, z]. GLB only. */
  size: z.tuple([z.number(), z.number(), z.number()]).optional(),
  /** FBX only: texture PNGs to attach by material name. */
  textures: z.array(z.string()).optional(),
});
export type ManifestModel = z.infer<typeof ManifestModel>;

export const AssetManifest = z.object({
  version: z.literal(1),
  packs: z.record(
    z.string(),
    z.object({ author: z.string(), source: z.string(), licence: z.string(), licenceFile: z.string() }),
  ),
  models: z.array(ManifestModel),
});
export type AssetManifest = z.infer<typeof AssetManifest>;
